installer-gui-script.script:
function checkDymoDriver() {
    if (!system.files.fileExistsAtPath('/Library/Printers/DYMO')) {
        my.result.title = 'DYMO printer driver not found';
        my.result.message = 'Install DYMO Connect for Desktop first (it provides the LabelWriter driver), then run this installer. You can continue anyway, but printing will not work until the driver is installed.';
        my.result.type = 'Warn';
        return false;
    }
    return true;
}
